package main

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shiraz Phone</title>
<style>
:root{font-family:system-ui,sans-serif;color:#e8e8e8;background:#000;color-scheme:dark}
*{box-sizing:border-box}html{background:#000}body{margin:0;min-height:100vh;background:radial-gradient(ellipse 52% 42% at 70% 42%,#d8e6ff0c,transparent 75%),#000;line-height:1.7;-webkit-font-smoothing:antialiased}
button,input{font:inherit}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid #fff;outline-offset:3px}
main{max-width:1120px;margin:auto;padding:72px 32px 48px}
.status{display:inline-block;margin:18px 0 0;font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:#777}.status:before{content:'';display:inline-block;width:6px;height:6px;background:#666;border-radius:50%;margin-right:9px;vertical-align:2px}.status.online:before{background:#d8e6ff;box-shadow:0 0 8px #d8e6ff80}
.layout{display:grid;grid-template-columns:minmax(280px,440px) minmax(330px,1fr);gap:clamp(40px,7vw,100px);align-items:center;max-width:960px;margin:auto}
.phone{width:min(100%,390px);margin:auto;padding:10px;border:1px solid #4c4c4c;border-radius:43px;background:#080808;box-shadow:0 0 0 4px #151515,0 26px 80px #000;position:relative}.earpiece{height:16px;width:76px;border-radius:0 0 12px 12px;background:#080808;position:absolute;top:0;left:50%;transform:translateX(-50%);z-index:2}.screen{position:relative;aspect-ratio:9/16;overflow:hidden;background:#0c0c0c;border-radius:34px;touch-action:none;user-select:none}.screen img{display:block;width:100%;height:100%;object-fit:fill;visibility:hidden}.screen.ready img{visibility:visible}.empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:30px;color:#777;font-size:13px}.empty .icon{font-size:32px;font-weight:200;color:#bdbdbd;margin-bottom:20px}.empty strong{color:#f2f2f2;font-size:18px;font-weight:450;margin-bottom:7px}.screen.ready .empty{display:none}.nav{height:40px;display:flex;align-items:center;justify-content:space-around}.nav button{border:0;background:none;color:#aaa;font-size:23px;cursor:pointer;width:52px;height:36px;line-height:1}.nav button:hover{color:#fff}
.panel{padding:14px 0}.eyebrow{font-size:10px;letter-spacing:1.3px;text-transform:uppercase;color:#777;margin:0 0 30px}.panel h2{font-size:clamp(32px,4.2vw,48px);font-weight:450;letter-spacing:-1.7px;line-height:1.16;color:#f2f2f2;margin:0}.muted{font-size:15px;color:#999;line-height:1.8;margin:22px 0 0;max-width:470px}.card{background:#080808;border:1px solid #242424;border-radius:8px;padding:24px;margin-top:30px}.card label{display:block;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#aaa;margin-bottom:15px}.card input[type=file],.card input[type=text]{display:block;width:100%;border:1px solid #3a3a3a;border-radius:4px;background:#101010;color:#d2d2d2;padding:12px;font-size:13px}.card input[type=file]::file-selector-button{color:#eee;background:#242424;border:1px solid #404040;border-radius:3px;padding:7px 11px;margin-right:12px;cursor:pointer}.primary{display:inline-block;background:#f2f2f2;border:1px solid #f2f2f2;border-radius:4px;color:#080808;font-size:12px;font-weight:600;letter-spacing:.02em;padding:11px 17px;margin-top:18px;cursor:pointer;transition:background .18s,border-color .18s}.primary:hover{background:#c8d0da;border-color:#c8d0da}.primary:disabled{opacity:.45;cursor:wait}.note{font-size:11px;color:#777;margin:16px 0 0}.logs{margin-top:24px;border-top:1px solid #242424;padding-top:16px}.logs summary{cursor:pointer;color:#999;font-size:12px}.logs pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:290px;overflow:auto;background:#080808;border:1px solid #242424;border-radius:5px;padding:14px;color:#aaa;font-size:11px;line-height:1.5}
footer{max-width:960px;margin:64px auto 0;border-top:1px solid #242424;padding:18px 0;font-size:11px;color:#606060;display:flex;justify-content:space-between;gap:20px}footer a{color:#aaa;text-decoration:none}footer a:hover{color:#fff}
@media(max-width:760px){main{padding:32px 24px}.status{font-size:11px}.layout{grid-template-columns:1fr;gap:38px}.panel{order:-1;padding:0}.phone{max-width:345px}.eyebrow{margin-bottom:18px}.panel h2{font-size:36px}.card{margin-top:24px}footer{margin-top:44px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><main><div class="layout"><div class="phone"><div id="screen" class="screen"><div class="earpiece"></div><img id="frame" alt="Live Android app screen" draggable="false"><div class="empty"><div class="icon">◇</div><strong>Your app appears here</strong><span>Upload an APK to start the phone.</span></div></div><div class="nav"><button id="back" title="Back" aria-label="Back">‹</button><button id="stop" title="Stop app" aria-label="Stop app">○</button><button id="refresh" title="Refresh screen" aria-label="Refresh screen">↻</button></div></div><section class="panel"><p class="eyebrow">03 / ANDROID · TRANSLATION LAYER</p><h2>Android apps.<br>Linux, your way.</h2><span id="status" class="status" role="status" aria-live="polite">Connecting</span><p class="muted">Choose an APK. Shiraz runs it on this Linux server and shows its screen here. Touch or drag the phone screen to interact.</p><form id="form" class="card"><label for="apk">APK file</label><input id="apk" name="apk" type="file" accept=".apk,application/vnd.android.package-archive" required><button class="primary" id="send" disabled>Upload and run</button><p class="note">One app at a time · Up to 256 MiB · 30 minute session</p></form><div class="logs"><details><summary>Run log</summary><pre id="log"></pre></details></div></section></div><footer><span>SpectreOSS / Shiraz · Experimental</span><a href="https://spectre-oss.github.io/">Back to SpectreOSS ↗</a></footer></main>
<script>
const status=document.querySelector('#status'),screen=document.querySelector('#screen'),frame=document.querySelector('#frame'),send=document.querySelector('#send'),log=document.querySelector('#log');let ws,connected=false,drag=false;
function setStatus(message,online){status.textContent=message;status.classList.toggle('online',online)}
function connect(){ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws');ws.onopen=()=>{connected=true;send.disabled=false;setStatus('Connected',true)};ws.onmessage=e=>{const msg=JSON.parse(e.data);if(msg.type==='status')setStatus(msg.message,true);else{log.textContent+=msg.message+'\n';log.scrollTop=log.scrollHeight;if(msg.type==='error')setStatus('Run failed',false)}};ws.onclose=()=>{connected=false;send.disabled=true;setStatus('Reconnecting',false);setTimeout(connect,1500)}}
connect();function input(action,x=0,y=0){if(connected)ws.send(JSON.stringify({action,x,y}))}function point(e){const r=screen.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
const controls=document.createElement('div');controls.className='card';controls.innerHTML='<label for="typing">Type into the app</label><input id="typing" type="text" maxlength="30" placeholder="Text for the focused field" ><button id="type-send" class="primary" type="button">Send text</button><button id="enter" class="primary" type="button" style="margin-left:8px;background:#101010;color:#eee;border-color:#454545">Enter</button>';document.querySelector('.panel').insertBefore(controls,document.querySelector('.logs'));document.querySelector('#type-send').onclick=()=>{const field=document.querySelector('#typing');if(field.value&&connected){ws.send(JSON.stringify({action:'text',text:field.value}));field.value=''}};document.querySelector('#enter').onclick=()=>input('enter');
screen.addEventListener('pointerdown',e=>{if(!screen.classList.contains('ready'))return;drag=true;screen.setPointerCapture(e.pointerId);const p=point(e);input('fingerdown',p.x,p.y)});screen.addEventListener('pointermove',e=>{if(drag){const p=point(e);input('fingermove',p.x,p.y)}});function end(e){if(drag){drag=false;const p=point(e);input('fingerup',p.x,p.y)}}screen.addEventListener('pointerup',end);screen.addEventListener('pointercancel',end);document.querySelector('#back').onclick=()=>input('back');document.querySelector('#stop').onclick=()=>input('stop');document.querySelector('#refresh').onclick=()=>refresh();
async function refresh(){try{const response=await fetch('/frame.png?t='+Date.now(),{cache:'no-store'});if(!response.ok)return;const blob=await response.blob(),url=URL.createObjectURL(blob),old=frame.src;frame.onload=()=>{screen.classList.add('ready');if(old.startsWith('blob:'))URL.revokeObjectURL(old)};frame.src=url}catch{}}setInterval(refresh,350);
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();send.disabled=true;log.textContent='';screen.classList.remove('ready');setStatus('Uploading',true);try{const response=await fetch('/upload',{method:'POST',body:new FormData(e.target)});if(!response.ok)throw Error((await response.text()).trim());setStatus('Starting',true)}catch(error){setStatus('Upload failed',false);log.textContent=error.message}finally{send.disabled=false}};
</script></body></html>`
